// Generated by vibelang from src/preview/AnnotationKeyboard.ts; the migrate flow writes it again with each batch.
export function resolveAnnotationSubmission(event, canSend) {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing)
        return null;
    return event.metaKey || event.ctrlKey ? (canSend ? "send" : null) : "attach";
}
